165	                    &self.partition_by.clone(),
166	                    reverse_order_bys(self.order_by.as_ref()).as_ref(),
167	                    Arc::new(self.window_frame.reverse()),
168	                )) as _
169	            }
170	        })
171	    }
172	
173	    fn uses_bounded_memory(&self) -> bool {
174	        !self.window_frame.end_bound.is_unbounded()
175	    }
